<script setup lang="ts">
import {useVehicleStore} from '../stores/vehicle';import {windowConfig} from '../config/v8-windows';
import {modelReviewEnabled} from '../config/runtime';
const quality=new URLSearchParams(location.search).get('quality')||'auto';
function changeQuality(event:Event){const url=new URL(location.href);const value=(event.target as HTMLSelectElement).value;if(value==='auto')url.searchParams.delete('quality');else url.searchParams.set('quality',value);location.href=url.href;}
const store=useVehicleStore();defineProps<{baseline:boolean}>();const emit=defineEmits<{inspect:[]}>();
</script><template><details><summary>演示与调试</summary><label>画质（切换后重新加载）<select :value="quality" @change="changeQuality"><option value="auto">自动</option><option value="high">高清</option><option value="balanced">均衡</option><option value="low">流畅</option></select></label>          <div class="playback"><div><strong>连续检查</strong><label>单程 <select v-model.number="store.seconds" aria-label="单程时长"><option :value="2">2 秒</option><option :value="5">5 秒</option><option :value="10">10 秒</option></select></label></div><button class="primary" @click="store.togglePlayback()">{{ store.playing ? 'Ⅱ 暂停在当前位置' : '▷ 循环升降四窗' }}</button></div>
        <p v-if="modelReviewEnabled"><a :href="baseline ? './' : '?baseline=1'">{{ baseline ? '返回修正轨迹' : '查看旧轨迹对照' }}</a></p><button v-if="modelReviewEnabled" class="mesh-check" @click="store.setAll(1); emit('inspect')">前窗网格检查（全开）</button><p v-if="modelReviewEnabled" class="diagnostic-note">网格视图：青色为主玻璃，线框为内饰板；旧轨迹对照中的红点为实际三角面交点。</p><details><summary>模型与运动说明</summary><p>V8 Executive 0.1 · GTV Lab。保留原始 FBX；发布版GLB已包含门腔修正，未减面。玻璃透明度固定。</p><p>前窗：57 cm / 12°；后窗：55 cm / 18°。前内饰板背面局部让位，上沿开槽并补齐内侧门腰板。四窗各 101 个开度对门皮、内饰板和新增板件未检出三角面相交；不代表所有零件的连续碰撞证明。</p><p class="node">当前节点：{{ windowConfig[store.selected].node }}</p><p>运动配置：src/config/v8-windows.ts</p></details></details></template>
